&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-size: 12pt; font-family: &#39;times new roman&#39;, times, serif;&quot;&gt;Role Overview&lt;/span&gt;&lt;/p&gt;
